import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.CKZJaUMN.js";const u=JSON.parse('{"title":"Wire API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/wire-api.md","filePath":"reference/wire-api.md"}'),i={name:"reference/wire-api.md"};function r(c,e,n,s,p,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="wire-api" tabindex="-1">Wire API <a class="header-anchor" href="#wire-api" aria-label="Permalink to &quot;Wire API&quot;">​</a></h1><p>The entity-plane HTTP surface (served by the node host, aggregated by the hub). Routes land with <code>hypha-http</code>/<code>hypha-hub</code> in P3; the shapes below are the contract <code>hypha-node-api</code> already codes against.</p><h2 id="node-surface-—-api-entities" tabindex="-1">Node surface — <code>/api/entities*</code> <a class="header-anchor" href="#node-surface-—-api-entities" aria-label="Permalink to &quot;Node surface — `/api/entities*`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Verb</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/entities</code></td><td>GET</td><td>list entities (<code>?kind=</code>, <code>?withLocks=1</code>)</td></tr><tr><td><code>/api/entities</code></td><td>POST</td><td>create entity (kind-registered)</td></tr><tr><td><code>/api/entities/{id}</code></td><td>GET/DELETE</td><td>entity detail / delete (<code>entity.delete</code> op)</td></tr><tr><td><code>/api/entities/{id}/ops</code></td><td>POST</td><td>submit op <code>{kind, payload}</code></td></tr><tr><td><code>/api/entities/{id}/snapshot</code></td><td>GET</td><td>export snapshot bytes</td></tr><tr><td><code>/api/entities/snapshot</code></td><td>POST</td><td>import snapshot onto this node</td></tr></tbody></table><h2 id="hub-surface" tabindex="-1">Hub surface <a class="header-anchor" href="#hub-surface" aria-label="Permalink to &quot;Hub surface&quot;">​</a></h2><p>Same <code>/api/entities*</code> shape, aggregated: merged index from all <code>HYPHA_NODES</code>/<code>PEREGRIN_NODES</code>, ops routed to the owner (outbox queued when offline), <code>/api/events</code> SSE diff feed, push bridges.</p><h2 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h2><p><code>hypha_node_api::HttpEntityApi</code> (ureq) implements <code>EntityApi</code>; <code>FakeEntityApi</code> is the in-memory test double. Wire DTOs: <code>EntityDto</code>, <code>EntityOp</code>, <code>EntityIndexDto</code>, <code>PendingOpDto</code>, <code>NodeInfoDto</code>, <code>NodeStatusDto</code>, <code>PushSubscriptionDto</code> — see <code>hypha-node-api/src/dto.rs</code> and the generated rustdoc under <code>/hypha/api/</code>.</p>',8)])])}const f=t(i,[["render",r]]);export{u as __pageData,f as default};
